package main

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"

	"kvhttp/internal/kv"
)

const (
	kvPrefix     = "/kv/"
	maxKeyLength = 64
	maxBodyBytes = 1 << 20 // 1 MiB
)

// handler routes requests to the key/value store. It deliberately does not
// use http.ServeMux so that paths are matched exactly as sent, without
// cleaning or redirects.
type handler struct {
	store *kv.Store
}

func newHandler(store *kv.Store) *handler {
	return &handler{store: store}
}

func (h *handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.EscapedPath()
	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, "GET")
			return
		}
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		io.WriteString(w, "ok")
	case path == "/kv":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, "GET")
			return
		}
		h.listKeys(w)
	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !validKey(key) {
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		h.handleKey(w, r, key)
	default:
		w.WriteHeader(http.StatusNotFound)
	}
}

func (h *handler) handleKey(w http.ResponseWriter, r *http.Request, key string) {
	switch r.Method {
	case http.MethodGet:
		value, ok := h.store.Get(key)
		if !ok {
			w.WriteHeader(http.StatusNotFound)
			return
		}
		w.Header().Set("Content-Type", "application/octet-stream")
		w.Header().Set("Content-Length", strconv.Itoa(len(value)))
		w.Write(value)
	case http.MethodPut:
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
		if err != nil {
			if _, ok := errors.AsType[*http.MaxBytesError](err); ok {
				w.WriteHeader(http.StatusRequestEntityTooLarge)
			} else {
				w.WriteHeader(http.StatusBadRequest)
			}
			return
		}
		if h.store.Put(key, body) {
			w.WriteHeader(http.StatusCreated)
		} else {
			w.WriteHeader(http.StatusOK)
		}
	case http.MethodDelete:
		if h.store.Delete(key) {
			w.WriteHeader(http.StatusNoContent)
		} else {
			w.WriteHeader(http.StatusNotFound)
		}
	default:
		methodNotAllowed(w, "GET, PUT, DELETE")
	}
}

func (h *handler) listKeys(w http.ResponseWriter) {
	keys := h.store.Keys()
	if keys == nil {
		keys = []string{} // encode as [] rather than null
	}
	body, err := json.Marshal(keys)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.Write(body)
}

func methodNotAllowed(w http.ResponseWriter, allow string) {
	w.Header().Set("Allow", allow)
	w.WriteHeader(http.StatusMethodNotAllowed)
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > maxKeyLength {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"

	"kvhttp/internal/kv"
)

func newTestServer(t *testing.T) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(newHandler(kv.NewStore()))
	t.Cleanup(srv.Close)
	return srv
}

func do(t *testing.T, srv *httptest.Server, method, path string, body []byte) (int, http.Header, []byte) {
	t.Helper()
	var r io.Reader
	if body != nil {
		r = bytes.NewReader(body)
	}
	req, err := http.NewRequest(method, srv.URL, r)
	if err != nil {
		t.Fatal(err)
	}
	req.URL.Opaque = path // send the path verbatim
	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	return resp.StatusCode, resp.Header, data
}

func TestRoutes(t *testing.T) {
	srv := newTestServer(t)
	big := bytes.Repeat([]byte{0xff}, maxBodyBytes)

	steps := []struct {
		method, path string
		body         []byte
		status       int
		want         string
	}{
		{"GET", "/health", nil, 200, "ok"},
		{"POST", "/health", nil, 405, ""},
		{"GET", "/kv", nil, 200, "[]"},
		{"POST", "/kv", nil, 405, ""},
		{"PUT", "/kv/b", []byte("2"), 201, ""},
		{"PUT", "/kv/a", []byte{}, 201, ""},
		{"PUT", "/kv/a", []byte("1"), 200, ""},
		{"GET", "/kv/a", nil, 200, "1"},
		{"GET", "/kv", nil, 200, `["a","b"]`},
		{"PATCH", "/kv/a", nil, 405, ""},
		{"DELETE", "/kv/a", nil, 204, ""},
		{"DELETE", "/kv/a", nil, 404, ""},
		{"GET", "/kv/a", nil, 404, ""},
		{"GET", "/kv/", nil, 400, ""},
		{"GET", "/kv/a/b", nil, 400, ""},
		{"GET", "/kv/bad.key", nil, 400, ""},
		{"GET", "/kv/%41", nil, 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 65), nil, 400, ""},
		{"PATCH", "/kv/bad.key", nil, 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 64), nil, 404, ""},
		{"GET", "/nope", nil, 404, ""},
		{"GET", "/kv/../health", nil, 400, ""},
		{"PUT", "/kv/big", big, 201, ""},
		{"GET", "/kv/big", nil, 200, string(big)},
		{"PUT", "/kv/huge", append(big, 0), 413, ""},
	}
	for _, s := range steps {
		status, _, body := do(t, srv, s.method, s.path, s.body)
		if status != s.status || string(body) != s.want {
			t.Errorf("%s %s = %d (%d bytes), want %d (%d bytes)", s.method, s.path, status, len(body), s.status, len(s.want))
		}
	}
}

func TestConcurrent(t *testing.T) {
	srv := newTestServer(t)
	var wg sync.WaitGroup
	for i := range 128 {
		wg.Go(func() {
			key := fmt.Sprintf("/kv/k%d", i)
			val := []byte(strings.Repeat("v", i*1000))
			if status, _, _ := do(t, srv, "PUT", key, val); status != 201 {
				t.Errorf("PUT %s = %d", key, status)
			}
			if status, _, body := do(t, srv, "GET", key, nil); status != 200 || !bytes.Equal(body, val) {
				t.Errorf("GET %s = %d", key, status)
			}
		})
	}
	wg.Wait()
}

// Package kv provides a thread-safe in-memory key/value store.
package kv

import (
	"maps"
	"slices"
	"sync"
)

// Store is a concurrency-safe map from keys to byte values. Stored values
// are treated as immutable: callers must not modify a slice after passing it
// to Put or after receiving it from Get.
type Store struct {
	mu sync.RWMutex
	m  map[string][]byte
}

// NewStore returns an empty store.
func NewStore() *Store {
	return &Store{m: make(map[string][]byte)}
}

// Put stores value under key. It reports whether the key was newly created
// (true) or an existing value was replaced (false).
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.m[key]
	s.m[key] = value
	return !exists
}

// Get returns the value stored under key and whether it was present.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.m[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.m[key]; !ok {
		return false
	}
	delete(s.m, key)
	return true
}

// Keys returns every key in ascending byte-wise order.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := slices.Collect(maps.Keys(s.m))
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

package kv

import (
	"slices"
	"testing"
)

func TestStore(t *testing.T) {
	s := NewStore()
	if !s.Put("b", []byte("1")) {
		t.Fatal("first Put should create")
	}
	if s.Put("b", []byte("2")) {
		t.Fatal("second Put should replace")
	}
	s.Put("a", nil)
	if v, ok := s.Get("b"); !ok || string(v) != "2" {
		t.Fatalf("Get(b) = %q, %v", v, ok)
	}
	if got := s.Keys(); !slices.Equal(got, []string{"a", "b"}) {
		t.Fatalf("Keys() = %v", got)
	}
	if !s.Delete("a") || s.Delete("a") {
		t.Fatal("Delete should succeed once")
	}
	if _, ok := s.Get("a"); ok {
		t.Fatal("deleted key still present")
	}
}

// Command app is an HTTP/1.1 in-memory key/value server.
//
// Usage:
//
//	app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/kv"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: %s <port>\n", os.Args[0])
		os.Exit(2)
	}
	port, err := strconv.ParseUint(os.Args[1], 10, 16)
	if err != nil || port == 0 {
		fmt.Fprintf(os.Stderr, "invalid port: %s\n", os.Args[1])
		os.Exit(2)
	}
	if err := run(net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10))); err != nil {
		log.Fatalf("fatal: %v", err)
	}
}

func run(addr string) error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           newHandler(kv.NewStore()),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       30 * time.Second,
		MaxHeaderBytes:    64 << 10,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()

	select {
	case err := <-errc:
		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return err
	case <-ctx.Done():
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		return srv.Shutdown(shutdownCtx)
	}
}
